#include <string_view>

std::string_view dayName(int day)
{
    switch (day)
    {
    case 1: return "Monday";
    case 2: return "Tuesday";
    case 3: return "Wednesday";
    case 4: return "Thursday";
    case 5: return "Friday";
    case 6: return "Saturday";
    case 7: return "Sunday";
    default: return "unknown";
    }
}

unitTests:
TEST("weekdays") { CHECK_EQ(dayName(1), "Monday"); CHECK_EQ(dayName(3), "Wednesday"); CHECK_EQ(dayName(5), "Friday"); }
TEST("weekend") { CHECK_EQ(dayName(6), "Saturday"); CHECK_EQ(dayName(7), "Sunday"); }
TEST("the rest") { CHECK_EQ(dayName(2), "Tuesday"); CHECK_EQ(dayName(4), "Thursday"); }
TEST("out of range") { CHECK_EQ(dayName(0), "unknown"); CHECK_EQ(dayName(8), "unknown"); }

